package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;

/** Real editor/storage flow, with no scheduler, playback, camera, brightness or alarm Service. */
public class AlarmWakeSettingsTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private View named(View root,String value,boolean description){if(description?android.text.TextUtils.equals(value,root.getContentDescription()):root instanceof android.widget.TextView&&android.text.TextUtils.equals(value,((android.widget.TextView)root).getText()))return root;if(root instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=named(group.getChildAt(n),value,description);if(found!=null)return found;}return null;}
    private AlarmEditorActivity editor(){for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof AlarmEditorActivity)return (AlarmEditorActivity)a;throw new AssertionError("A resumed alarm editor is required");}
    private boolean completeControl(String description){boolean[] complete={false};i.runOnMainSync(()->{View target=named(editor().toneCaptureView(),description,true);if(target==null)return;android.graphics.Rect visible=new android.graphics.Rect();complete[0]=target.isAttachedToWindow()&&target.getGlobalVisibleRect(visible)&&visible.height()==target.getHeight()&&visible.width()==target.getWidth()&&visible.height()>=Design.dp(c,48)&&visible.width()>=Design.dp(c,48);});return complete[0];}
    private UiObject object(String description)throws Exception{
        device.waitForIdle();UiSelector selector=new UiSelector().description(description);UiObject value=device.findObject(selector);
        // A below-viewport control may not exist in the accessibility tree until scrolled into view.
        if(!value.exists()||!completeControl(description)){
            UiScrollable page=new UiScrollable(new UiSelector().scrollable(true));
            if(page.exists()){
                assertTrue("Scroll to "+description,page.scrollIntoView(selector));
                i.runOnMainSync(()->{View target=named(editor().toneCaptureView(),description,true);assertNotNull("Native control "+description,target);target.requestRectangleOnScreen(new android.graphics.Rect(0,0,target.getWidth(),target.getHeight()),true);});device.waitForIdle();
            }else assertTrue("A fitting page or opening dialog must expose "+description,value.waitForExists(5000));
        }
        assertTrue("Ready control "+description,value.waitForExists(5000));assertTrue("Visible complete 48 dp control "+description,completeControl(description));return value;
    }
    private AlarmRampChart chart(View root){if(root instanceof AlarmRampChart)return (AlarmRampChart)root;if(root instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){AlarmRampChart found=chart(group.getChildAt(n));if(found!=null)return found;}return null;}
    private void assertChart(String expected){i.runOnMainSync(()->{AlarmEditorActivity current=editor();View root=current.getWindow().getDecorView();assertTrue("Gentle page window has focus",root.hasWindowFocus());assertNotNull("Actual gentle page heading",named(root,"Gentle wake-up",false));AlarmRampChart plot=chart(root);assertNotNull("Actual native planned-volume chart",plot);assertEquals("Current draft curve must be rendered",expected,plot.getContentDescription().toString());android.graphics.Rect visible=new android.graphics.Rect();assertTrue("Chart visible",plot.isAttachedToWindow()&&plot.getGlobalVisibleRect(visible));assertEquals("Entire chart height",plot.getHeight(),visible.height());assertEquals("Entire chart width",plot.getWidth(),visible.width());assertTrue("Nonempty chart",visible.height()>0&&visible.width()>0);});}
    private void awaitGentleFocus()throws Exception{
        CountDownLatch focus=new CountDownLatch(1);View[] root={null};android.view.ViewTreeObserver.OnWindowFocusChangeListener listener=hasFocus->{if(hasFocus)focus.countDown();};
        i.runOnMainSync(()->{root[0]=editor().getWindow().getDecorView();root[0].getViewTreeObserver().addOnWindowFocusChangeListener(listener);if(root[0].hasWindowFocus())focus.countDown();});
        try{assertTrue("Gentle page regains focus after its dialog closes",focus.await(5,TimeUnit.SECONDS));}finally{i.runOnMainSync(()->{if(root[0].getViewTreeObserver().isAlive())root[0].getViewTreeObserver().removeOnWindowFocusChangeListener(listener);});}
    }
    private void curveCapture(String name,int target,int rampSeconds,int delaySeconds)throws Exception{
        String expected="Planned volume curve: "+target+" percent after "+rampSeconds+" seconds of gradual increase. Sound starts after "+delaySeconds+" seconds. Device volume steps may round the final level.";
        assertTrue("Exact gentle draft chart is ready",device.wait(Until.hasObject(By.desc(expected)),5000));assertTrue("Actual gentle page heading is ready",device.wait(Until.hasObject(By.text("Gentle wake-up")),5000));assertFalse("Previous sound page cannot qualify",device.hasObject(By.text("Alarm sound")));
        device.waitForIdle();awaitGentleFocus();assertChart(expected);capture(name);assertChart(expected);
    }
    private void click(String text)throws Exception{UiObject2 value=device.wait(Until.findObject(By.text(text)),1000);if(value==null)value=device.wait(Until.findObject(By.desc(text)),2000);if(value==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(text));value=device.wait(Until.findObject(By.text(text)),5000);}assertNotNull(text,value);value.click();device.waitForIdle();}
    private void vibrationChoice(String value)throws Exception{assertTrue("The vibration dialog is open",device.wait(Until.hasObject(By.text("Vibration starts")),5000));UiObject2 choice=device.wait(Until.findObject(By.desc(value)),5000);assertNotNull(value,choice);choice.click();assertTrue("The timing dialog must close before another control is used",device.wait(Until.gone(By.text("Vibration starts")),5000));assertTrue("The applied timing must appear inside its own control",device.wait(Until.hasObject(By.desc("Vibration starts").hasDescendant(By.text(value))),5000));}
    private void capture(String name)throws Exception{CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED)){View decor=a.getWindow().getDecorView();decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();}});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"wake-settings-"+name+".png")));}
    private void launch(Alarm alarm,String route){c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("route",route).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));assertTrue(device.wait(Until.hasObject(By.text(route.equals("gentle")?"Gentle wake-up":"Alarm sound")),5000));}
    private void recreateEditor(){final Activity[] current={null};i.runOnMainSync(()->{for(Activity activity:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(activity instanceof AlarmEditorActivity)current[0]=activity;});assertNotNull(current[0]);Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(current[0]::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}}
    @Test public void actualDraftRecreationSaveReopenAndCancelWithoutOutputs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(Prefs.flag(c,"ringing"));assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        String database="sleepwell-wake-settings-"+UUID.randomUUID()+".db";Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());Records.Factory priorRecords=Records.factory;AlarmScheduling.Port priorScheduling=AlarmScheduling.port;List<Activity> owned=new CopyOnWriteArrayList<>();int[] scheduled={0};
        Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);assertFalse(a instanceof AlarmActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);
        try{
            Records.factory=context->new Store(context,database);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse("Only disabled fixture may save",alarm.enabled);scheduled[0]++;}};
            Alarm fixture=new Alarm(1);fixture.volume=80;fixture.rampSeconds=120;fixture.label="Wake-up settings";fixture.vibrate=true;org.json.JSONObject legacy=fixture.json();legacy.remove("vibrationDelaySeconds");assertEquals("Existing alarms vibrate immediately",0,Alarm.read(legacy).vibrationDelaySeconds);try(Store store=new Store(c,database)){store.save(fixture);}
            launch(fixture,"sound");capture("sound");object("Alarm sound options").click();assertFalse(object("Extra loud").isChecked());object("Extra loud").click();click("Gentle wake-up");curveCapture("loud-curve",100,120,0);
            object("Vibration starts").click();assertTrue(device.wait(Until.hasObject(By.text("After 1 min")),5000));recreateEditor();assertTrue("Open vibration timing dialog survives recreation",device.wait(Until.hasObject(By.text("Vibration starts")),5000));assertTrue(device.wait(Until.hasObject(By.desc("From start").selected(true)),5000));capture("vibration-options");vibrationChoice("After 1 min");object("Vibration starts").click();assertTrue("The next timing dialog must show the current selection",device.wait(Until.hasObject(By.desc("After 1 min").selected(true)),5000));click("Cancel");assertTrue("Cancellation closes the dialog",device.wait(Until.gone(By.text("Vibration starts")),5000));assertTrue("Cancellation retains the prior timing in its control",device.wait(Until.hasObject(By.desc("Vibration starts").hasDescendant(By.text("After 1 min"))),5000));
            object("Sound delay").click();assertTrue("Duration choice must be visible before selecting",device.wait(Until.hasObject(By.text("3 min")),5000));capture("delay-options");click("3 min");object("Vibration").click();assertFalse(object("Vibration starts").isEnabled());object("Screen sunrise").click();object("Flashlight wake-up").click();capture("lights");
            recreateEditor();
            assertTrue(object("Screen sunrise").isChecked());assertTrue(object("Flashlight wake-up").isChecked());assertFalse(object("Vibration").isChecked());assertTrue(device.hasObject(By.text("After 1 min")));assertFalse(object("Vibration starts").isEnabled());capture("recreated");click("Save changes");click("Use Daybreak");click("Save alarm");
            Alarm saved;try(Store store=new Store(c,database)){saved=store.alarm(1);}assertNotNull(saved);assertTrue(saved.extraLoud);assertTrue(saved.sunrise);assertTrue(saved.flashlight);assertFalse(saved.vibrate);assertEquals(60,saved.vibrationDelaySeconds);assertEquals(180,saved.soundDelaySeconds);assertEquals(120,saved.rampSeconds);assertEquals(80,saved.volume);assertEquals(1,scheduled[0]);
            launch(saved,"gentle");assertTrue(device.hasObject(By.text("After 1 min")));curveCapture("reopened",100,120,180);click("Save changes");object("Alarm sound options").click();assertTrue(object("Extra loud").isChecked());object("Extra loud").click();click("Gentle wake-up");curveCapture("normal-curve",80,120,180);object("Vibration").click();assertTrue(object("Vibration starts").isEnabled());object("Vibration starts").click();vibrationChoice("After 2 min");object("Volume ramp").click();click("1 min");curveCapture("edited-curve",80,60,180);object("Volume ramp").click();click("Off");curveCapture("immediate",80,0,180);device.pressBack();assertTrue(device.wait(Until.hasObject(By.text("Alarm sound")),5000));device.pressBack();assertTrue(device.wait(Until.hasObject(By.text("Edit alarm")),5000));device.pressBack();assertFalse(device.wait(Until.hasObject(By.text("Edit alarm")),1000));
            try(Store store=new Store(c,database)){assertEquals(saved.json().toString(),store.alarm(1).json().toString());}assertEquals(1,scheduled[0]);assertEquals(personal,Prefs.of(c).getAll());assertFalse(Prefs.flag(c,"ringing"));assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        }catch(Exception|AssertionError failure){try{device.dumpWindowHierarchy(new File(c.getExternalFilesDir(null),"verification/wake-settings-failure.xml"));capture("failure");}catch(Exception|AssertionError diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{
            try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}
            finally{app.unregisterActivityLifecycleCallbacks(lifecycle);Records.factory=priorRecords;AlarmScheduling.port=priorScheduling;if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(database);}
        }
    }
}
